function decodeCayenneLPP(hex) {
  var bytes = Buffer.from(hex, 'hex');
  var decoded = {};
  var i = 0;

  while (i < bytes.length) {
    var channel = bytes[i++];
    var type = bytes[i++];

    if (type === 0x00) {                          // Digital Input (1 byte) — ch 7-10
      decoded['digital_input_' + channel] = bytes[i++];

    } else if (type === 0x01) {                   // Digital Output (1 byte) — ch 11,12
      decoded['digital_output_' + channel] = bytes[i++];

    } else if (type === 0x8E) {                   // Switch Output (1 byte, RAK)
      decoded['switch_output_' + channel] = bytes[i++];

    } else if (type === 0x65) {                   // Illuminance / Luminosity (2 bytes, 1 lux)
      decoded['illuminance_' + channel] = (bytes[i] << 8) | bytes[i + 1];
      i += 2;

    } else if (type === 0x67) {                   // Temperature (2 bytes signed, 0.1 °C)
      var raw = (bytes[i] << 8) | bytes[i + 1];
      decoded['temperature_' + channel] = (raw >= 0x8000 ? raw - 0x10000 : raw) / 10;
      i += 2;

    } else if (type === 0x68) {                   // Relative Humidity (1 byte, 0.5 %)
      decoded['humidity_' + channel] = bytes[i++] / 2;

    } else if (type === 0x73) {                   // Barometric Pressure (2 bytes, 0.1 hPa)
      decoded['barometric_pressure_' + channel] = ((bytes[i] << 8) | bytes[i + 1]) / 10;
      i += 2;

    } else if (type === 0x71) {                   // Accelerometer (6 bytes, 0.001 g)
      var x = (bytes[i] << 8) | bytes[i + 1];
      var y = (bytes[i + 2] << 8) | bytes[i + 3];
      var z = (bytes[i + 4] << 8) | bytes[i + 5];
      decoded['accelerometer_' + channel] = {
        x: (x >= 0x8000 ? x - 0x10000 : x) / 1000,
        y: (y >= 0x8000 ? y - 0x10000 : y) / 1000,
        z: (z >= 0x8000 ? z - 0x10000 : z) / 1000
      };
      i += 6;

    } else if (type === 0x74) {                   // Voltage / Battery (2 bytes, 0.01 V)
      decoded['battery_voltage_' + channel] = ((bytes[i] << 8) | bytes[i + 1]) / 100;
      i += 2;

    } else if (type === 0x86) {                   // Gyrometer (6 bytes, 0.01 °/s)
      decoded['gyrometer_' + channel] = {
        x: ((bytes[i] << 8) | bytes[i + 1]) / 100,
        y: ((bytes[i + 2] << 8) | bytes[i + 3]) / 100,
        z: ((bytes[i + 4] << 8) | bytes[i + 5]) / 100
      };
      i += 6;

    } else if (type === 0x88) {                   // GPS (9 bytes)
      decoded['gps_' + channel] = {
        latitude: ((bytes[i] << 16) | (bytes[i + 1] << 8) | bytes[i + 2]) / 10000,
        longitude: ((bytes[i + 3] << 16) | (bytes[i + 4] << 8) | bytes[i + 5]) / 10000,
        altitude: ((bytes[i + 6] << 16) | (bytes[i + 7] << 8) | bytes[i + 8]) / 100
      };
      i += 9;

    } else if (type === 0x8A) {                   // VOC / Gas resistance (2 bytes uint16, kΩ)
      decoded['gas_resistance_' + channel] = (bytes[i] << 8) | bytes[i + 1];
      i += 2;

    } else {
      node.warn('Unknown LPP type 0x' + type.toString(16) + ' on channel ' + channel + ' at byte ' + (i - 2));
      break;
    }
  }

  return decoded;
}

// channel → logical field name
var channelNames = {
  1: 'battery_voltage',        // LPP_CHANNEL_BATT_1
  2: 'temperature',            // LPP_CHANNEL_TEMP_1   (RAK1901 / RAK1906)
  3: 'humidity',               // LPP_CHANNEL_HUMID_1  (RAK1901 / RAK1906)
  4: 'pressure',               // LPP_CHANNEL_PRESS_1  (RAK1902 / RAK1906)
  5: 'illuminance',            // LPP_CHANNEL_LIGHT_1  (RAK1903)
  6: 'accelerometer',          // LPP_CHANNEL_ACC_1    (RAK1904)
  7: 'version_byte',           // LPP_CHANNEL_DIG_1
  8: 'acc_threshold',          // LPP_CHANNEL_DIG_2
  9: 'acc_duration',           // LPP_CHANNEL_DIG_3
  10: 'acc_frequency',          // LPP_CHANNEL_DIG_4
  11: 'motion_switch',          // LPP_CHANNEL_DIG_5    (GPIO switch)
  12: 'motion_alert',           // LPP_CHANNEL_DIG_6    (RAK1904 interrupt)
  13: 'low_battery_shutdown',   // LPP_CHANNEL_DIG_7
  14: 'gas_resistance'          // LPP_CHANNEL_GAS_1    (RAK1906, kΩ)
};

var raw = decodeCayenneLPP(msg.payload);

// Remap generic "type_channel" keys to logical names
var decodedData = {};
for (var key in raw) {
  var match = key.match(/_(\d+)$/);
  if (match) {
    var ch = parseInt(match[1]);
    decodedData[channelNames[ch] || key] = raw[key];
  } else {
    decodedData[key] = raw[key];
  }
}

msg.payload = decodedData;
return msg;

